MERGE dbo.Permissions AS t USING (VALUES
('workspace.view','View workspace','Access workspace context','Workspace'),('workspace.manage','Manage workspace settings','Edit workspace configuration','Workspace'),('users.view','View users','View workspace membership','Administration'),('users.manage','Manage users','Invite, edit and suspend users','Administration'),('roles.manage','Manage roles and permissions','Modify workspace RBAC','Administration'),('content.view','View content projects','Read content projects','Content'),('content.create','Create content projects','Create and edit production work','Content'),('content.approve','Approve workflow stages','Approve governed workflow gates','Content'),('agents.manage','Manage AI agents','Configure AI agents','Automation'),('integrations.manage','Manage provider integrations','Configure external providers','Automation'),('billing.view','View usage and cost','View platform consumption','Management'),('audit.view','View audit trail','Review security and business events','Management')) s(PermissionKey,DisplayName,Description,Category)
ON t.PermissionKey=s.PermissionKey WHEN MATCHED THEN UPDATE SET DisplayName=s.DisplayName,Description=s.Description,Category=s.Category WHEN NOT MATCHED THEN INSERT(PermissionKey,DisplayName,Description,Category) VALUES(s.PermissionKey,s.DisplayName,s.Description,s.Category);
GO
INSERT dbo.RolePermissions(RoleId,PermissionId)
SELECT r.RoleId,p.PermissionId FROM dbo.Roles r CROSS JOIN dbo.Permissions p WHERE r.Name='Super Admin' AND NOT EXISTS(SELECT 1 FROM dbo.RolePermissions rp WHERE rp.RoleId=r.RoleId AND rp.PermissionId=p.PermissionId);
GO
